<?php $page='notifications';$title='Notifications';require_once __DIR__.'/includes/functions.php';require_login();$uid=$_SESSION['user_id'];verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$q->execute([$uid]);set_flash('Notifications marked as read.');header('Location: notifications.php');exit;}$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC');$q->execute([$uid]);$rows=$q->fetchAll();require 'includes/header.php';?>
<div class="page-head"><div><h1>Notifications</h1><p>Budget alerts and account updates.</p></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn secondary">Mark all as read</button></form></div><div class="card"><?php foreach($rows as $r):?><div class="list-item"><strong><?=e($r['message'])?></strong><div class="muted"><?=e($r['created_at'])?> · <?=$r['is_read']?'Read':'Unread'?></div></div><?php endforeach;if(!$rows):?><p class="empty">You have no notifications.</p><?php endif;?></div><?php require 'includes/footer.php';?>
